extern "C" u8 pachiruEffectCreate(PachiruEffect*effect,GSmodel*model,u32 seed){u8 success=0;if(!model)return 0;GSpart*part=GSmodelGetPart(model,2);if(!part)return 0;effect->material=0;effect->texture=0;effect->material=GSpartGetMaterial(part,0);if(effect->material){GStexture*base=(GStexture*)GSresGetResource(903,0xF7D1200);if(base){GStexture*patch=(GStexture*)GSresGetResource(903,0xF7E1200);if(patch){effect->texture=_pachiruEffectCreateTexture(base,patch,seed);if(effect->texture){GSmaterialSetTexture(effect->material,effect->texture);success=1;}}}}if(!success){if(effect->texture){GStextureFree(effect->texture);effect->texture=0;}effect->material=0;}GSpartFree(part);return success;}
static GStexture*_pachiruEffectCreateTexture(GStexture*base,GStexture*patch,unsigned long seed){u16*source=0;s16 width=GStextureGetXsize(base);s16 height=GStextureGetYsize(base);s32 levels=GStextureGetMiplevels(base);s32 tlut=GStextureGetTlutFormat(base);GStexture*texture=GStextureCreate(width,height,GStextureGetFormat(base),tlut,levels);u16*image=(u16*)GStextureLockImage(texture,0);if(image){source=(u16*)GStextureLockImage(base,0);if(source){s32 pixels=width*height;s32 bytes=pixels*2;memcpy(image,source,bytes);DCFlushRange(image,bytes);GStextureUnlockImage(base);GStextureConvertFromHW(texture);GStextureConvertFromHW(patch);source=(u16*)GStextureLockImage(patch,0);if(source){s16 patchWidth=GStextureGetXsize(patch);s16 patchHeight=GStextureGetYsize(patch);if(patchWidth<=(width>>2)&&patchHeight<=(height>>2)){u16*last=image+pixels-1;u8*coord=&gPachiruCoords[0][0];for(s16 i=0;i<4;coord+=2,i++){s16 pixel=0;s16 dy=((seed>>4)&15)-8;s16 dx=(seed&15)-8;s32 row=0;seed>>=8;for(s16 y=0;y<patchHeight;pixel+=patchWidth,row+=width,y++){s16 offset=(s16)((s32)(3.4f*dx)+coord[0]+(((s32)(3.4f*dy)+coord[1])*width))+row;if(offset>=0){u16*destination=image+offset;if(destination<=last){u16*input=source+pixel;for(s16 x=0;x<patchWidth;x++,destination++,input++){if(destination<=last){u16 color=*input;if(color>*destination)*destination=color;}}}}}}GStextureUnlockImage(texture);GStextureUnlockImage(patch);GStextureConvertToHW(patch);GStextureConvertToHW(texture);return texture;}}}}GSlogWrite("Failed to create Patchiru texture\n");if(image)GStextureUnlockImage(texture);if(source)GStextureUnlockImage(patch);if(texture)GStextureFree(texture);return 0;}
